import type { NodeMap } from '../compiler/types.ts';
import { whitespaceTrivia, type WhitespaceTrivia } from '../compiler/model/trivia.ts';
import { compareOrdinal } from './shared.ts';
import { grammarTypeMapName } from './engine.ts';

export interface EmitClientUtilsConfig {
	grammar: string;
	nodeMap: NodeMap;
	triviaKinds?: string[];
}

export function emitClientUtils(config: EmitClientUtilsConfig): string {
	const map = grammarTypeMapName(config.grammar);
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		"import type { AnyNodeData, TriviaFacts } from '@sittir/types';",
		"import { bindRuntime } from '@sittir/common/utils';",
		`import { KIND_NAMES, type ${map} } from './types.js';`,
		"import { INNER_GAPS } from './consts.js';",
		'',
		...emitTriviaFacts(whitespaceTrivia(config.nodeMap), config.triviaKinds ?? []),
		'',
		`export const { isNode, isEmpty, withMethods } = bindRuntime<${map}>(triviaFacts);`,
		''
	].join('\n');
}

function emitTriviaFacts(whitespace: WhitespaceTrivia | undefined, triviaKinds: readonly string[]): string[] {
	const facts = [
		"    kindName: (type: AnyNodeData['$type']) => (typeof type === 'number' ? KIND_NAMES.get(type) : type)",
		`    kinds: new Set<string>(${JSON.stringify([...triviaKinds].sort(compareOrdinal))})`,
		'    innerGaps: INNER_GAPS',
		...(whitespace === undefined
			? []
			: [
					`    whitespace: { run: /${whitespace.run.source}/${whitespace.run.flags}, kindIdByText: ${JSON.stringify(Object.fromEntries(whitespace.kindIdByText))} }`
				])
	];
	return ['export const triviaFacts = {', facts.join(',\n'), '} satisfies TriviaFacts;'];
}

export function resolveTriviaTypeNames(triviaKinds: readonly string[], nodeMap: NodeMap): string[] {
	const names = triviaKinds
		.map((kind) => nodeMap.nodes.get(kind)?.typeName)
		.filter((name): name is string => name !== undefined);
	return [...new Set(names)].sort();
}

export function buildTriviaNodeType(triviaTypeNames: readonly string[]): string {
	return triviaTypeNames.length > 0 ? triviaTypeNames.join(' | ') : 'AnyNodeData';
}
